import { io } from 'socket.io-client';

const socket = io('http://localhost:3000', {
	autoConnect: false,
	reconnection: true,
	reconnectionDelay: 1000,
	reconnectionDelayMax: 5000,
	reconnectionAttempts: 5
});

// Handle authentication
socket.on('connect', () => {
	console.log('Connecté au serveur');
	const token = localStorage.getItem('token');

	if (token) {
		try {
			// Vérifier si le token est au format JWT valide
			const parts = token.split('.');
			if (parts.length === 3) {
				// Envoyer le token brut
				socket.emit('authenticate', token);
				console.log('Token envoyé pour authentification');
			} else {
				console.error('Format de token invalide');
				socket.disconnect();
			}
		} catch (error) {
			console.error('Erreur lors de la vérification du token:', error);
			socket.disconnect();
		}
	} else {
		console.log('Aucun token trouvé');
		socket.disconnect();
	}
});

socket.on('authenticated', () => {
	console.log('Socket authentifié avec succès');
});

socket.on('disconnect', () => {
	console.log('Déconnecté du serveur');
});

socket.on('error', (error) => {
	console.error('Erreur socket:', error);
});

socket.on('authentication_error', (error) => {
	console.error('Erreur d\'authentification:', error);
	// Déconnecter le socket en cas d'erreur d'authentification
	socket.disconnect();
});

export { socket };
